mod tests {
    use super::*;
    use aws_smithy_types::Document;
    use serde_json::json;

    #[test]
    fn null_bool_string() {
        assert!(matches!(value_to_document(&json!(null)), Document::Null));
        assert!(matches!(
            value_to_document(&json!(true)),
            Document::Bool(true)
        ));
        assert!(matches!(value_to_document(&json!("x")), Document::String(s) if s == "x"));
